import React from "react";
import { Form, Label, Input, Textarea, Button } from "../../../Utils/Styled";

type Props = {
  form: any;
  loading: boolean;
  modalMode: "add" | "edit";
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => void;
  onSubmit: (e: React.FormEvent) => void;
  onCancel: () => void;
};

const StudentForm: React.FC<Props> = ({
  form,
  loading,
  modalMode,
  onChange,
  onSubmit,
  onCancel,
}) => (
  <Form onSubmit={onSubmit}>
    <Label>
      Name:
      <Input name="name" value={form.name} onChange={onChange} required />
    </Label>
    <Label>
      Email:
      <Input name="email" value={form.email} onChange={onChange} />
    </Label>
    <Label>
      Phone:
      <Input name="phone" value={form.phone} onChange={onChange} />
    </Label>
    <Label>
      Date of Birth:
      <Input name="dateOfBirth" value={form.dateOfBirth} onChange={onChange} type="date" />
    </Label>
    <Label>
      Notes:
      <Textarea name="notes" value={form.notes} onChange={onChange} />
    </Label>
    <div>
      <Button type="submit" disabled={loading}>
        {modalMode === "add" ? "Add Student" : "Update Student"}
      </Button>
      <Button
        type="button"
        variant="secondary"
        onClick={onCancel}
      >
        Cancel
      </Button>
    </div>
  </Form>
);

export default StudentForm;