import { useState } from "react";

type ModalsState = {
  upsert: boolean;
  delete: boolean;
};

const getInitialModalsState = (): ModalsState => ({
  upsert: false,
  delete: false,
});

type EntityType = "student" | "lessonRecurring";

export const useModals = () => {
  const [modals, setModals] = useState<ModalsState>(getInitialModalsState());

  const [itemToDelete, setItemToDelete] = useState<any | null>(null);
  const [itemTypeToDelete, setItemTypeToDelete] = useState<'student' | 'lessonRecurring' | null>(null);
  const [upsertEntityType, setUpsertEntityType] = useState<EntityType>("student");
  const [editingId, setEditingId] = useState<string | undefined>(undefined);

  const openUpsertModal = (entityType: EntityType = "student", id?: string) => {
    const modalsState = getInitialModalsState();
    modalsState.upsert = true;
    setUpsertEntityType(entityType);
    setEditingId(id);
    setModals(modalsState);
  };

  const openDeleteModal = (item: any, itemType: 'student' | 'lessonRecurring') => {
    const modalsState = getInitialModalsState();
    modalsState.delete = true;
    setItemToDelete(item);
    setItemTypeToDelete(itemType);
    setModals(modalsState);
  };

  const closeAllModals = () => {
    setItemToDelete(null);
    setItemTypeToDelete(null);
    setEditingId(undefined);
    const modalsState = getInitialModalsState();
    setModals(modalsState);
  };

  return {
    modals,
    itemToDelete,
    itemTypeToDelete,
    upsertEntityType,
    editingId,
    openUpsertModal,
    openDeleteModal,
    closeAllModals,
    setModals,
    setItemToDelete,
  };
};
