import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { AppDispatch } from "../../../store/store";
import {
  ModalOverlayBlur,
  ModalContent,
  ModalClose,
  Label,
  ModalFormGroup,
  ModalInput,
  ModalActions,
  ActionButton,
  StatusBadge,
  SignatureSection,
  SignatureTitle,
  SignatureContainer,
  SignatureBox,
  SignatureDisplay,
} from "../../Utils/Styled";
import { lessonInstanceActions } from "../../../store/lessonSlice";
import { LessonInstance } from "../../../models/LessonInstance";

const handleDeleteLesson = async (
  closeAllModals: () => void,
  lessonToDelete: LessonInstance | null,
  dispatch: AppDispatch
) => {
  if (!lessonToDelete) return;

  if (!window.confirm("Are you sure you want to delete this lesson?")) {
    return;
  }
  lessonToDelete = {... lessonToDelete}; // Create a shallow copy to avoid direct state mutation

  // Handle delete when event is a unacknowledged lesson instance
  if (lessonToDelete.status === "unacknowledged") {
    lessonToDelete.type = 'cancelled';
    lessonToDelete.actualFee = 0;
    await dispatch(lessonInstanceActions.update(lessonToDelete));
  }
  // Handle delete when event is a recurring lesson
  else if (lessonToDelete.lessonRecurringId && !lessonToDelete._id) {
    console.log("Deleting recurring lesson instance:", lessonToDelete);
    const recurringLessonToDelete: LessonInstance = {
              ...lessonToDelete,
              _id: '',
              type: 'cancelled',
              status: 'scheduled',
              expectedFee: 0,
              actualFee: 0,
              cancelledReason: 'Lesson cancelled',
              createdAt: new Date(),
              updatedAt: new Date(),
            };
    await dispatch(lessonInstanceActions.add(recurringLessonToDelete));
  }
  // Handle delete when event is an existing lesson instance
  else if (lessonToDelete._id) {
    await dispatch(lessonInstanceActions.remove(lessonToDelete._id));
  }
  closeAllModals();
};

const handleRestoreLesson = async (
  closeAllModals: () => void,
  lessonToRestore: LessonInstance | null,
  dispatch: AppDispatch
) => {
    if (!lessonToRestore) return;
    if (!window.confirm("Are you sure you want to restore this lesson?")) return;

    const updatedLesson = {
      ...lessonToRestore,
      status: "scheduled" as const,
    };
    await dispatch(lessonInstanceActions.update(updatedLesson) as any);
    closeAllModals();
  };

interface ViewEventModalProps {
  isOpen: boolean;
  studentName: string;
  lessonInstance: LessonInstance | null;
  eventStart: Date;
  eventEnd: Date;
  closeAllModals: () => void;
  openEditEventModal: () => void;
  openCompleteLessonModal: (expectedFee: number) => void;
  openCancelLessonModal: () => void;
}

const ViewEventModal: React.FC<ViewEventModalProps> = ({
  isOpen,
  studentName,
  lessonInstance,
  eventStart,
  eventEnd,
  closeAllModals,
  openEditEventModal,
  openCompleteLessonModal,
  openCancelLessonModal,
}) => {
  const dispatch = useDispatch<AppDispatch>();

  if (!lessonInstance) return null;

  const formatDateToLocalDatetimeInput = (date: Date) => {
    const pad = (num: number) => num.toString().padStart(2, "0");
    const year = date.getFullYear();
    const month = pad(date.getMonth() + 1);
    const day = pad(date.getDate());
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  if(!isOpen) return null;

  return (
    <ModalOverlayBlur onClick={closeAllModals}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={closeAllModals} aria-label="Close modal">
          &times;
        </ModalClose>
        <h2>View Lesson</h2>
          <ModalFormGroup>
            <ModalFormGroup>
              <StatusBadge status={lessonInstance.status ?? "scheduled"}>
                {lessonInstance.status}
              </StatusBadge>
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Student:</Label>
              <ModalInput
                type="text"
                value={studentName}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Date:</Label>
              <ModalInput
                type="date"
                value={formatDateToLocalDatetimeInput(eventStart).split('T')[0]}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>Start Time:</Label>
              <ModalInput
                type="time"
                value={formatDateToLocalDatetimeInput(eventStart).split('T')[1] || '00:00'}
                disabled={true}
              />
            </ModalFormGroup>
            <ModalFormGroup>
              <Label>End Time:</Label>
              <ModalInput
                type="time"
                value={formatDateToLocalDatetimeInput(eventEnd).split('T')[1] || '00:00'}
                disabled={true}
              />
            </ModalFormGroup>
            {lessonInstance.status === "completed" && (
              <>
              <ModalFormGroup>
                <Label>Fee Paid:</Label>
                <ModalInput
                  type="string"
                  value={`$${lessonInstance.actualFee?.toFixed(2) ?? '0.00'}`}
                  disabled={true}
                />
              </ModalFormGroup>
                <SignatureSection>
                    <SignatureTitle>
                      Signatures
                    </SignatureTitle>
          
                    <SignatureContainer>
                      {/* Section 1: Teacher Signature */}
                      <SignatureBox>
                        <SignatureDisplay>
                          <img
                            src={lessonInstance.teacherSignature?.imageUrl}
                            alt="Teacher signature"
                          />
                        </SignatureDisplay>
                      </SignatureBox>
          
                      {/* Section 2: Student Signature */}
                      <SignatureBox>
                        <SignatureDisplay>
                          <img
                            src={lessonInstance?.studentSignature?.imageUrl}
                            alt="Student signature"
                          />
                        </SignatureDisplay>
                      </SignatureBox>
                    </SignatureContainer>
                  </SignatureSection>
              </>
            )}
            <ModalActions>
              {lessonInstance.status === "scheduled" && (
                <>
                  <ActionButton
                    variant="primary"
                    type="button"
                    onClick={openEditEventModal}
                  >
                    Edit
                  </ActionButton>
                  <ActionButton
                    variant="secondary"
                    type="button"
                    onClick={() => {closeAllModals(); openCancelLessonModal(); }}
                  >
                    Cancel Lesson
                  </ActionButton>
                </>
              )}
              {lessonInstance.status === "cancelled" && (
                <>
                <ModalFormGroup>
                  <Label>Cancelled Reason:</Label>
                  <ModalInput
                    type="text"
                    value={lessonInstance.cancelledReason || 'No reason provided'}
                    disabled={true}
                  />
                </ModalFormGroup>
                  <ActionButton
                    variant="success"
                    type="button"
                    onClick={handleRestoreLesson.bind(null, closeAllModals, lessonInstance, dispatch)}
                  >
                    Restore Lesson
                  </ActionButton>
                </>
              )}
              {lessonInstance.status === "unacknowledged" && (
                <>
                  <ActionButton
                    variant="primary"
                    type="button"
                    onClick={openEditEventModal}
                  >
                    Edit
                  </ActionButton>
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <ActionButton
                      variant="secondary"
                      type="button"
                      onClick={() => {closeAllModals(); openCancelLessonModal(); }}
                    >
                      Cancel Lesson
                    </ActionButton>
                    <ActionButton
                      variant="success"
                      type="button"
                      onClick={() => openCompleteLessonModal(lessonInstance.expectedFee || 0)}
                    >
                      Complete Lesson
                    </ActionButton>
                  </div>
                </>
              )}
              <ActionButton
                variant="danger"
                type="button"
                onClick={handleDeleteLesson.bind(null, closeAllModals, lessonInstance, dispatch)}
              >
                Delete From Calendar
              </ActionButton>
              {lessonInstance.status === "completed" && (
                <ActionButton
                  variant="secondary"
                  type="button"
                  onClick={closeAllModals}>
                  Cancel
                </ActionButton>
              )}
            </ModalActions>
          </ModalFormGroup>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default ViewEventModal;
