import React from "react";
import {
  ModalOverlay,
  ModalContent,
  ModalClose,
  Button,
  SignatureSection,
  SignatureTitle,
  SignatureContainer,
  SignatureBox,
  SignatureDisplay,
  ModalActions,
  ActionButton,
  Input,
  Label,
} from "../Styled";
import { LessonInstance } from "../../../models/LessonInstance";
import { SignerRole } from "../hooks/useModals";

interface CompleteLessonModalProps {
  isOpen: boolean;
  lessonInstance: LessonInstance | null;
  setSignatureSigner: (signer: SignerRole) => void;
  openSignatureModal: () => void;
  teacherSignature: string | null;
  studentSignature: string | null;
  feePaid: string;
  setFeePaid: (fee: string) => void;
  onSubmit: () => void;
  onClose: () => void;
}

const CompleteLessonModal: React.FC<CompleteLessonModalProps> = ({
  isOpen,
  lessonInstance,
  setSignatureSigner,
  openSignatureModal,
  teacherSignature,
  studentSignature,
  feePaid,
  setFeePaid,
  onSubmit,
  onClose,
}) => {
  if (!lessonInstance || !isOpen) return null;

  const handleAddSignature = (role: SignerRole) => {
    setSignatureSigner(role);
    openSignatureModal();
  };

  return (
    <ModalOverlay onClick={onClose}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={onClose} aria-label="Close modal">
          &times;
        </ModalClose>
        <h2>Complete Lesson</h2>
        <SignatureSection>
          <SignatureTitle>
            Signatures
          </SignatureTitle>

          <SignatureContainer>
            {/* Section 1: Teacher Signature */}
            <SignatureBox>
              <SignatureDisplay>
                <img
                  src={teacherSignature || lessonInstance.teacherSignature?.imageUrl}
                  alt="Teacher signature"
                />
              </SignatureDisplay>
              {teacherSignature || lessonInstance.teacherSignature ?
                null :
                <Button
                  variant="primary"
                  type="button"
                  onClick={() => handleAddSignature("teacher")}
                  style={{ width: "100%" }}
                >
                  Add Teacher Signature
                </Button>
              }
            </SignatureBox>

            {/* Section 2: Student Signature */}
            <SignatureBox>
              <SignatureDisplay>
                <img
                  src={studentSignature || lessonInstance.studentSignature?.imageUrl}
                  alt="Student signature"
                />
              </SignatureDisplay>
              {studentSignature || lessonInstance.studentSignature ?
                null :
                <Button
                  variant="primary"
                  type="button"
                  onClick={() => handleAddSignature("student")}
                  style={{ width: "100%" }}
                >
                  Add Student Signature
                </Button>
              }
            </SignatureBox>
          </SignatureContainer>
        </SignatureSection>
        <div style={{ marginTop: "20px" }}>
          <Label>
            Fee Paid ($)
            <Input
              type="number"
              value={feePaid}
              onChange={(e) => setFeePaid(e.target.value)}
              placeholder="Enter fee paid"
              min="0"
              step="0.01"
            />
          </Label>
        </div>
        <ModalActions>
          <ActionButton
            variant="secondary"
            type="button"
            onClick={onClose}>
            Cancel
          </ActionButton>
          <ActionButton
            variant="primary"
            type="button"
            onClick={onSubmit}
            disabled={!teacherSignature || !studentSignature || !feePaid.trim()}
          >
            Submit
          </ActionButton>
        </ModalActions>
      </ModalContent>
    </ModalOverlay>
  );
};

export default CompleteLessonModal;
