import { LessonRecurring, DayOfWeek } from '../../../models/LessonRecurring';
import { LessonInstance } from '../../../models/LessonInstance';
import { Student } from '../../../models/Student';

// Helper function to safely convert date string to Date object
function parseDate(dateString: string): Date {
  const date = new Date(dateString);
  if (isNaN(date.getTime())) {
    throw new Error(`Invalid date string: ${dateString}`);
  }
  return date;
}

// Helper function to compare two date strings as Date objects
function compareDateStrings(dateStr1: string, dateStr2: string): number {
  const date1 = parseDate(dateStr1);
  const date2 = parseDate(dateStr2);
  return date1.getTime() - date2.getTime();
}

// Helper function to get all dates between two dates
function getDatesBetween(startDate: string, endDate: string): string[] {
  const dates = [];
  let currentDate = new Date(startDate);
  const lastDate = new Date(endDate);
  while (currentDate <= lastDate) {
    dates.push(currentDate.toISOString().split('T')[0]);
    currentDate.setDate(currentDate.getDate() + 1);
  }
  return dates;
}

// Calendar event interface for react-big-calendar
export interface CalendarEvent {
  id: number;
  title: string;
  start: Date;
  end: Date;
  resource?: LessonInstance;
  status?: "scheduled" | "completed" | "unacknowledged" | "cancelled";
}

// Generate all calendar events from both lesson instances and recurring lessons
export function generateCalendarEvents(
  lessonInstances: LessonInstance[],
  lessonRecurrings: LessonRecurring[],
  students: Student[],
  fromDate: string,
  toDate: string,
  selectedStudentIds: string[] = []
): CalendarEvent[] {
  const allEvents: CalendarEvent[] = [];

  if (fromDate > toDate) {
    return allEvents; // Return empty if date range is invalid
  }

  // Create a map of students by ID for quick lookup
  const studentMap = new Map<string, Student>();
  for (const student of students) {
    studentMap.set(student._id, student);
  }

  // Filter instances and recurrings based on selected students
  let filteredInstances = lessonInstances;
  let filteredRecurrings = lessonRecurrings;
  if (selectedStudentIds.length > 0) {
    const selectedSet = new Set(selectedStudentIds);
    filteredInstances = lessonInstances.filter((instance: LessonInstance) => selectedSet.has(instance.studentId));
    filteredRecurrings = lessonRecurrings.filter((recurring: LessonRecurring) => selectedSet.has(recurring.studentId));
  }

  // Create a map of existing instances by date and startTime for quick lookup
  const existingMap = new Map<string, LessonInstance>();
  for (const instance of filteredInstances) {
    const key = instance.date + '|' + instance.startTime;
    existingMap.set(key, instance);
  }
  
  // Create a set to track rescheduled recurring lesson slots
  const rescheduledSlots = new Set<string>();
  
  // Process lesson instances to identify rescheduled lessons
  filteredInstances.forEach((instance: LessonInstance) => {
    if (instance.type === "rescheduled" && instance.rescheduledFromDate && instance.rescheduledFromStartTime) {
      // Mark the original recurring slot as rescheduled
      const originalKey = instance.rescheduledFromDate + '|' + instance.rescheduledFromStartTime;
      rescheduledSlots.add(originalKey);
    }
  });
  
  // Process lesson instances into calendar events
  filteredInstances.forEach((instance: LessonInstance, index: number) => {
    const startDateTime = new Date(`${instance.date}T${instance.startTime}`);
    const endDateTime = new Date(`${instance.date}T${instance.endTime}`);
    
    const student = studentMap.get(instance.studentId);
    const studentName = student ? student.name : "Unknown Student";
    let title = `${studentName}`;

    // Skip cancelled lessons from calendar (status = "cancelled" means no makeup and will be shown as grayed out in calendar)
    if (instance.type === "cancelled") {
      return;
    }
  
    // Skip out of range dates
    if (instance.date < fromDate || instance.date > toDate) {
      return;
    }
    
    allEvents.push({
      id: index + 1,
      title,
      start: startDateTime,
      end: endDateTime,
      resource: instance
    });
  });
  
  // Process recurring lessons directly into calendar events
  filteredRecurrings.forEach((recurring: LessonRecurring, recurringIndex: number) => {
    const startDate = compareDateStrings(recurring.startDate, fromDate) > 0 ? recurring.startDate : fromDate;
    const endDate = recurring.endDate && compareDateStrings(recurring.endDate, toDate) < 0 ? recurring.endDate : toDate;
    
    const allDates = getDatesBetween(startDate, endDate);
    
    for (const date of allDates) {
      const dayOfWeek = new Date(date).toLocaleDateString('en-US', { weekday: 'long' }) as DayOfWeek;
      
      if (recurring.dayOfWeek === dayOfWeek) {
        const key = date + '|' + recurring.startTime;
        
        // Skip if this recurring is already covered by an existing instance
        if (existingMap.has(key)) {
          continue;
        }
        
        // Skip if this recurring slot has been rescheduled
        if (rescheduledSlots.has(key)) {
          continue;
        }
        
        const startDateTime = new Date(`${date}T${recurring.startTime}`);
        const endDateTime = new Date(`${date}T${recurring.endTime}`);
        
        // Continue if this event already exists in allEvents
        const exists = allEvents.some(event => 
          event.start.getTime() === startDateTime.getTime() && 
          event.end.getTime() === endDateTime.getTime()
        );
        if (exists) {
          continue; 
        }
        
        const student = studentMap.get(recurring.studentId);
        const studentName = student ? student.name : "Unknown Student";
        
        // Create a proper LessonInstance structure for recurring lessons
        const lessonInstance: LessonInstance = {
          _id: "", // no ID for recurring lessons
          studentId: recurring.studentId,
          lessonRecurringId: recurring._id || '',
          date: date,
          startTime: recurring.startTime,
          endTime: recurring.endTime,
          type: "regular",
          status: "scheduled",
          expectedFee: recurring.fee || 0,
          actualFee: 0,
          createdAt: new Date(),
          updatedAt: new Date(),
        };
        
        allEvents.push({
          id: allEvents.length + 1000 + recurringIndex, // Offset to avoid ID conflicts
          title: `${studentName}`,
          start: startDateTime,
          end: endDateTime,
          resource: lessonInstance
        });
      }
    }
  });
  
  // Sort by date
  allEvents.sort((a, b) => a.start.getTime() - b.start.getTime());
  
  return allEvents;
}
