import React, { ChangeEvent, FormEvent, useState, useEffect } from "react";
import { useDispatch } from "react-redux";
import { AppDispatch } from "../../../store/store";
import { lessonInstanceActions } from "../../../store/lessonSlice";

import {
  ModalOverlayBlur,
  ModalContent,
  ModalClose,
  Button,
  Label,
  Input,
} from "../../Utils/Styled";
import { LessonInstance } from "../../../models/LessonInstance";

const handleSaveChanges = async (
  closeAllModals: () => void,
  lessonToSave: LessonInstance | null,
  dispatch: AppDispatch,
  newStart: Date,
  newEnd: Date
) => {
    if (!lessonToSave) return;

    if (newEnd <= newStart) {
      alert("End time must be after start time");
      return;
    }

    console.log("Saving changes for lesson:", lessonToSave);

    // Handle saving event that is from a recurring lesson 
    if (!lessonToSave._id && lessonToSave.lessonRecurringId) {
      // Create new lesson instance based on the recurring lesson
      const newLessonInstance: LessonInstance = {
        _id: '',
        studentId: lessonToSave.studentId,
        lessonRecurringId: lessonToSave.lessonRecurringId,
        date: newStart.toISOString().split("T")[0],
        startTime: newStart.toTimeString().split(" ")[0].substring(0, 5),
        endTime: newEnd.toTimeString().split(" ")[0].substring(0, 5),
        type: "regular",
        status: "scheduled",
        expectedFee: lessonToSave.expectedFee,
        actualFee: 0,
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      await dispatch(lessonInstanceActions.add(newLessonInstance));

      // Create a cancelled lesson instance to mark the original recurring lesson as cancelled on that date
      const cancelledLessonInstance: LessonInstance = {
        _id: '',
        studentId: lessonToSave.studentId,
        lessonRecurringId: lessonToSave.lessonRecurringId,
        date: lessonToSave.date,
        startTime: lessonToSave.startTime,
        endTime: lessonToSave.endTime,
        type: "cancelled",
        status: "cancelled",
        expectedFee: 0,
        actualFee: 0,
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      await dispatch(lessonInstanceActions.add(cancelledLessonInstance));

      console.log(newLessonInstance)
      console.log(cancelledLessonInstance)

      closeAllModals();
      return;
    }


    // Handle saving event that is already a lesson instance    
    const updatedLesson: LessonInstance = {
      ...lessonToSave,
      date: newStart.toISOString().split("T")[0],
      startTime: newStart.toTimeString().split(" ")[0].substring(0, 5),
      endTime: newEnd.toTimeString().split(" ")[0].substring(0, 5),
    }; 
    await dispatch(lessonInstanceActions.update(updatedLesson));
    closeAllModals();
  };

interface EditEventModalProps {
  isOpen: boolean;
  lessonInstance: LessonInstance;
  studentName: string;
  eventStart: Date;
  eventEnd: Date;
  closeAllModals: () => void;
}

const EditEventModal: React.FC<EditEventModalProps> = ({
  isOpen,
  lessonInstance,
  studentName,
  eventStart,
  eventEnd,
  closeAllModals,
}) => {
  const [editStart, setEditStart] = useState("");
  const [editEnd, setEditEnd] = useState("");
  const [editStudent, setEditStudent] = useState("");
  const dispatch = useDispatch<AppDispatch>();

  const formatDateToLocalDatetimeInput = (date: Date) => {
    if (!date ) return ``;
    const pad = (num: number) => num.toString().padStart(2, "0");
    const year = date.getFullYear();
    const month = pad(date.getMonth() + 1);
    const day = pad(date.getDate());
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  useEffect(() => {
    setEditStudent(studentName);
    setEditStart(formatDateToLocalDatetimeInput(eventStart));
    setEditEnd(formatDateToLocalDatetimeInput(eventEnd));
  }, [studentName, eventStart, eventEnd]);

  if (!lessonInstance || !studentName || !eventStart || !eventEnd ) return null;

  if (!isOpen) return null;

  return (
    <ModalOverlayBlur onClick={closeAllModals}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={closeAllModals} aria-label="Close modal">
          &times;
        </ModalClose>
        <h2>Edit Lesson</h2>
        <form onSubmit={(): Promise<void> =>
          handleSaveChanges(
            closeAllModals,
            lessonInstance,
            dispatch,
            new Date(editStart),
            new Date(editEnd)
          )
        }>
          <div style={{ marginBottom: "12px" }}>
            <div style={{ marginBottom: "12px" }}>
              <Label>Student:</Label>
              <Input
                type="text"
                value={editStudent}
                onChange={(e: ChangeEvent<HTMLInputElement>) => setEditStudent(e.target.value)}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>Date:</Label>
              <Input
                type="date"
                value={editStart.split('T')[0]}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const newDate = e.target.value;
                  const startTimePart = editStart.split('T')[1] || '00:00';
                  const endTimePart = editEnd.split('T')[1] || '00:00';
                  setEditStart(`${newDate}T${startTimePart}`);
                  setEditEnd(`${newDate}T${endTimePart}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>Start Time:</Label>
              <Input
                type="time"
                value={editStart.split('T')[1] || '00:00'}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const datePart = editStart.split('T')[0];
                  const newTime = e.target.value;
                  setEditStart(`${datePart}T${newTime}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginBottom: "12px" }}>
              <Label>End Time:</Label>
              <Input
                type="time"
                value={editEnd.split('T')[1] || '00:00'}
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  const datePart = editStart.split('T')[0];
                  const newTime = e.target.value;
                  setEditEnd(`${datePart}T${newTime}`);
                }}
                required
                style={{ width: "90%" }}
              />
            </div>
            <div style={{ marginTop: "20px", textAlign: "right" }}>
              <Button variant="secondary" type="button" onClick={closeAllModals}>
                Cancel
              </Button>
              <Button variant="primary" type="submit" style={{ marginLeft: "8px" }}>
                Save
              </Button>
            </div>
          </div>
        </form>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default EditEventModal;
