import React from "react";
import { ModalOverlayBlur, ModalContent, ModalClose, Button } from "../../Utils/Styled";
import { Student } from "../../../models/Student";
import { LessonRecurring } from "../../../models/LessonRecurring";

type DeleteItem = Student | LessonRecurring;

type Props = {
  open: boolean;
  onClose: () => void;
  itemToDelete: DeleteItem | null;
  onDelete: () => void;
  loading: boolean;
  itemType: 'student' | 'lesson';
};

const DeleteModal: React.FC<Props> = ({
  open,
  onClose,
  itemToDelete,
  onDelete,
  loading,
  itemType,
}) => {
  if (!open || !itemToDelete) return null;

  const getItemName = () => {
    if (itemType === 'student') {
      return (itemToDelete as Student).name;
    }
    // For LessonRecurring, we'll use a combination of student ID and schedule info
    const lesson = itemToDelete as LessonRecurring;
    const scheduleInfo = `${lesson.dayOfWeek} ${lesson.startTime}-${lesson.endTime}`
    return `Lesson: ${scheduleInfo}`;
  };

  const getModalTitle = () => {
    return itemType === 'student' ? 'Remove Student' : 'Remove Recurring Lesson';
  };

  const getConfirmationMessage = () => {
    const itemName = getItemName();
    return `Are you sure you want to remove ${itemType === 'student' ? '' : 'the'} <b>${itemName}</b>? This action cannot be undone.`;
  };

  return (
    <ModalOverlayBlur>
      <ModalContent>
        <h2 style={{ marginBottom: 18 }}>{getModalTitle()}</h2>
        <p dangerouslySetInnerHTML={{ __html: getConfirmationMessage() }} />
        <div style={{ marginTop: 24 }}>
          <Button variant="danger" onClick={onDelete} disabled={loading}>
            {loading ? 'Removing...' : 'Yes, Remove'}
          </Button>
          <Button
            type="button"
            variant="secondary"
            onClick={onClose}
            disabled={loading}
          >
            Cancel
          </Button>
        </div>
        <ModalClose onClick={onClose} disabled={loading}>×</ModalClose>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default DeleteModal;
