import React from "react";
import StudentForm from "./forms/StudentForm";
import LessonRecurringForm from "./forms/LessonRecurringForm";
import { ModalOverlayBlur, ModalContent, ModalClose } from "../../Utils/Styled";

type Props = {
  open: boolean;
  form: any;
  loading: boolean;
  modalMode: "add" | "edit";
  editingId?: string;
  entityType: "student" | "lessonRecurring";
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => void;
  onSubmit: (e: React.FormEvent) => void;
  onCancel: () => void;
};

const UpsertModal: React.FC<Props> = ({
  open,
  form,
  loading,
  modalMode,
  editingId,
  entityType,
  onChange,
  onSubmit,
  onCancel,
}) => {
  if (!open) return null;

  const getModalTitle = () => {
    const action = editingId ? "Edit" : "Add";

    if (entityType === "student") {
      return `${action} Student`;
    } else if (entityType === "lessonRecurring") {
      return `${action} Weekly Lesson`;
    }
    return "Upsert Modal";
  };

  const renderForm = () => {
    if (entityType === "student") {
      return (
        <StudentForm
          form={form}
          loading={loading}
          modalMode={modalMode}
          onChange={onChange}
          onSubmit={onSubmit}
          onCancel={onCancel}
        />
      );
    } else if (entityType === "lessonRecurring") {
      return (
        <LessonRecurringForm
          form={form}
          loading={loading}
          modalMode={modalMode}
          onChange={onChange}
          onSubmit={onSubmit}
          onCancel={onCancel}
        />
      );
    }
  };

  return (
    <ModalOverlayBlur>
      <ModalContent>
        <h2 style={{ marginBottom: 18 }}>{getModalTitle()}</h2>
        {renderForm()}
        <ModalClose onClick={onCancel}>×</ModalClose>
      </ModalContent>
    </ModalOverlayBlur>
  );
};

export default UpsertModal;
