import { useState } from 'react';

export type SignerRole = "teacher" | "student";

export const useCompleteLesson = () => {
  const [teacherSignature, setTeacherSignature] = useState<string | null>(null);
  const [studentSignature, setStudentSignature] = useState<string | null>(null);
  const [feePaid, setFeePaid] = useState<string>('');

  const setSignature = (role: SignerRole, signature: string | null) => {
    if (role === 'teacher') setTeacherSignature(signature);
    else if (role === 'student') setStudentSignature(signature);
  };

  const resetSignatures = () => {
    setTeacherSignature(null);
    setStudentSignature(null);
    setFeePaid('');
  };

  return { teacherSignature, studentSignature, feePaid, setFeePaid, setSignature, resetSignatures };
};
