import axios from "axios";
import { initializeApp } from "firebase/app";
import { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile, GoogleAuthProvider, signInWithPopup, getRedirectResult, onAuthStateChanged, signOut } from "firebase/auth";
import { getFirestore } from "firebase/firestore";

export interface User {
  id: string;
  email: string;
  name: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export interface LoginResponse {
  message: string;
  user: User;
}

export interface RegisterRequest {
  email: string;
  password: string;
  name: string;
}

export interface RegisterResponse {
  message: string;
  user: User & { createdAt: Date; updatedAt: Date };
}

class AuthService {
  IS_PROD: boolean = true;
  private static instance: AuthService;
  private prod_auth: any = "";
  private dev_url: string = "";
  private provider: GoogleAuthProvider | null = null;
  private app: any = null;
  private db: any = null;

  static getInstance(): AuthService {
    if (!AuthService.instance) {
      AuthService.instance = new AuthService();
    }
    return AuthService.instance;
  }

  constructor() {
    this.IS_PROD = !this.isLocalhost();
    this.initializeFirebase();
  }

  private isLocalhost() : boolean { 
    const is_localhost = window.location.hostname === 'localhost' ||
      window.location.hostname === '[::1]' ||
      window.location.hostname.match(/^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/);
    if (is_localhost) return true;
    return false;
  }

  private initializeFirebase() {
    const prodFirebaseConfig = {
      apiKey: process.env.REACT_APP_MAIN_FIREBASE_API_KEY,
      authDomain: process.env.REACT_APP_MAIN_FIREBASE_AUTH_DOMAIN,
      projectId: process.env.REACT_APP_MAIN_FIREBASE_PROJECT_ID,
      storageBucket: process.env.REACT_APP_MAIN_FIREBASE_STORAGE_BUCKET,
      messagingSenderId: process.env.REACT_APP_MAIN_FIREBASE_MESSAGING_SENDER_ID,
      appId: process.env.REACT_APP_MAIN_FIREBASE_APP_ID,
    };
    const testFirebaseConfig = {
      apiKey: process.env.REACT_APP_TEST_FIREBASE_API_KEY,
      authDomain: process.env.REACT_APP_TEST_FIREBASE_AUTH_DOMAIN,
      projectId: process.env.REACT_APP_TEST_FIREBASE_PROJECT_ID,
      storageBucket: process.env.REACT_APP_TEST_FIREBASE_STORAGE_BUCKET,
      messagingSenderId: process.env.REACT_APP_TEST_FIREBASE_MESSAGING_SENDER_ID,
      appId: process.env.REACT_APP_TEST_FIREBASE_APP_ID,
    };

    // Initialize Firebase
    let firebaseConfig;
    if (this.IS_PROD) {
      firebaseConfig = prodFirebaseConfig;
      this.app = initializeApp(prodFirebaseConfig);
    } else {
      firebaseConfig = testFirebaseConfig;
      this.app = initializeApp(testFirebaseConfig);
    }
    this.prod_auth = getAuth(this.app);
    this.db = getFirestore(this.app);
    this.provider = new GoogleAuthProvider();
  }

  async login(credentials: LoginRequest): Promise<LoginResponse> {
    try {
      const userCredential = await signInWithEmailAndPassword(this.prod_auth, credentials.email, credentials.password);
      const user = userCredential.user;
      return {
        message: 'Login successful',
        user: {
          id: user.uid,
          email: user.email || '',
          name: user.displayName || '',
        },
      };
    } catch (error) {
      console.error("Firebase login failed:", error);
      throw error;
    }
  }

  async signInWithGoogle(): Promise<void> {
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(this.prod_auth, provider);
      const user = result.user;
      console.log("User signed in:", user.displayName, user.email);
    } catch (error: any) {
      const errorCode = error.code;
      const errorMessage = error.message;
      const email = error.customData?.email;
      const credential = GoogleAuthProvider.credentialFromError(error);
      console.error("Error during Google sign-in:", errorCode, errorMessage, email, credential);
    }
  }

  setupAuthMonitoring(callback: (user: User | null) => void): void {
    if (!this.prod_auth) {
      throw new Error("Firebase auth not initialized.");
    }

    // Handle redirect result first, before setting up auth state listener
    getRedirectResult(this.prod_auth)
      .then((result) => {
        if (result) {
          const user = result.user;
          // Call callback with the user from redirect
          callback({
            id: user.uid,
            email: user.email || '',
            name: user.displayName || '',
          });
        } else {
        }
      })
      .catch((error: any) => {
        console.error("Error handling Google sign-in redirect:", error.code, error.message);
      });

    // Then set up auth state listener
    onAuthStateChanged(this.prod_auth, (user) => {
      callback(user ? {
        id: user.uid,
        email: user.email || '',
        name: user.displayName || '',
      } : null);
    });
  }

  async register(userData: RegisterRequest): Promise<RegisterResponse> {
    if (!this.IS_PROD) {
      try {
        const response = await axios.post<RegisterResponse>(`${this.dev_url}/users`, userData);
        return response.data;
      } catch (error) {
        console.error("Registration failed:", error);
        throw error;
      }
    } else {
      try {
        const userCredential = await createUserWithEmailAndPassword(this.prod_auth, userData.email, userData.password);
        const user = userCredential.user;
        await updateProfile(user, { displayName: userData.name });
        return {
          message: 'Registration successful',
          user: {
            id: user.uid,
            email: user.email || '',
            name: user.displayName || '',
            createdAt: new Date(user.metadata.creationTime || ''),
            updatedAt: new Date(user.metadata.lastSignInTime || ''),
          },
        };
      } catch (error) {
        console.error("Firebase registration failed:", error);
        throw error;
      }
    }
  }

  async logout(): Promise<void> {
    if (!this.IS_PROD) {
      // In development mode, just clear local storage
      localStorage.removeItem("user");
    } else {
      try {
        // In production mode, sign out from Firebase
        await signOut(this.prod_auth);
        localStorage.removeItem("user");
      } catch (error) {
        console.error("Firebase logout failed:", error);
        throw error;
      }
    }
  }

  // Export Firebase app and database instances for use by other services
  getFirebaseApp() {
    return this.app;
  }

  getFirestoreDb() {
    return this.db;
  }
}

export const authService = new AuthService();
