import React from "react";
import { HashRouter as Router, Routes, Route, Link, Navigate } from "react-router-dom";
import { StudentManagement } from "./components/StudentManagement";
import AppBar from "@mui/material/AppBar";
import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import Button from "@mui/material/Button";
import Box from "@mui/material/Box";
import TeachingSchedule from "./components/HomePage/TeachingSchedule";
import LessonOverview from "./components/LessonOverview";
import { AuthProvider, useAuth } from "./components/Auth/AuthContext";
import { authService } from "./services/authService";
import Login from "./components/Auth/Login";

const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isLoading } = useAuth();
  if (isLoading) {
    return <div>Loading...</div>; // Or a proper loading component
  }
  return isAuthenticated ? <>{children}</> : <Navigate to="/login" />;
};

const LoginRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isLoading } = useAuth();
  if (isLoading) {
    return <div>Loading...</div>; // Or a proper loading component
  }
  return isAuthenticated ? <Navigate to="/calendar" /> : <>{children}</>;
};

const AppContent: React.FC = () => {
  const { isAuthenticated, logout, user, isLoading } = useAuth();
  const IS_PROD = (authService as any).IS_PROD;
  const app_name = IS_PROD ? "Piano Planner" : "Piano Planner (Dev)";


  return (
    <>
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            {app_name}
          </Typography>
          {!isLoading && (
            isAuthenticated ? (
              <Box>
                <Typography variant="body1" sx={{ mr: 2 }}>
                  Welcome, {user? user.name? user.name : user.email : 'User'}
                </Typography>
                <Button color="inherit" component={Link} to="/calendar">
                  Calendar
                </Button>
                <Button color="inherit" component={Link} to="/overview">
                  Overview
                </Button>
                <Button color="inherit" component={Link} to="/students">
                  Students
                </Button>
                <Button color="inherit" onClick={logout}>
                  Logout
                </Button>
              </Box>
            ) : (
              <Button color="inherit" component={Link} to="/login">
                Login
              </Button>
            )
          )}
        </Toolbar>
      </AppBar>
      <Routes>
        <Route
          path="/login"
          element={
            <LoginRoute>
              <Login />
            </LoginRoute>
          }
        />
        <Route
          path="/calendar"
          element={
            <ProtectedRoute>
              <TeachingSchedule />
            </ProtectedRoute>
          }
        />
        <Route
          path="/overview"
          element={
            <ProtectedRoute>
              <LessonOverview />
            </ProtectedRoute>
          }
        />
        <Route
          path="/students"
          element={
            <ProtectedRoute>
              <StudentManagement />
            </ProtectedRoute>
          }
        />
        <Route path="/" element={<Navigate to="/calendar" />} />
      </Routes>
    </>
  );
};

const App: React.FC = () => (
  <AuthProvider>
    <Router>
      <AppContent />
    </Router>
  </AuthProvider>
);

export default App;