import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { AppDispatch } from "../../../store/store";
import {
  ModalOverlay,
  ModalContent,
  ModalClose,
  ModalActions,
  ActionButton,
  ModalFormGroup,
  ModalOverlayBlur,
  ModalInput,
  Label,
} from "../Styled";
import { lessonInstanceActions } from "../../../store/lessonSlice";
import { LessonInstance } from "../../../models/LessonInstance";

interface CancelLessonModalProps {
  isOpen: boolean;
  lessonInstance: LessonInstance | null;
  closeAllModals: () => void;
  onCancel: () => void;
}

const CancelLessonModal: React.FC<CancelLessonModalProps> = ({
  isOpen,
  lessonInstance,
  closeAllModals,
  onCancel,
}) => {
  const dispatch = useDispatch<AppDispatch>();
  const [cancelledReason, setCancelledReason] = useState("");

  if (!lessonInstance || !isOpen) return null;

  const handleConfirmCancel = async () => {
    const reason = cancelledReason.trim() || "Lesson cancelled";

    // Handle lesson when event is a future scheduled lesson generated from recurring lessons
    if (lessonInstance.lessonRecurringId && !lessonInstance._id) {
      const cancelledLesson: LessonInstance = {
        _id: '',
        studentId: lessonInstance.studentId,
        lessonRecurringId: lessonInstance.lessonRecurringId,
        date: lessonInstance.date,
        startTime: lessonInstance.startTime,
        endTime: lessonInstance.endTime,
        status: 'cancelled',
        type: 'regular',
        expectedFee: 0,
        actualFee: 0,
        cancelledReason: reason,
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      await dispatch(lessonInstanceActions.add(cancelledLesson));
      closeAllModals();
      return;
    }

    // Handle lesson when event is an existing lesson instance
    else if (lessonInstance._id) {
      const updatedLesson: LessonInstance = {
        ...lessonInstance,
        type: "regular",
        status: "cancelled",
        actualFee: 0,
        cancelledReason: reason,
      };
      await dispatch(lessonInstanceActions.update(updatedLesson) as any);
    }
    closeAllModals();
  };

  return (
    <ModalOverlayBlur onClick={closeAllModals}>
      <ModalOverlay onClick={closeAllModals}>
        <ModalContent onClick={(e) => e.stopPropagation()}>
          <ModalClose onClick={closeAllModals} aria-label="Close modal">
            &times;
          </ModalClose>
          <h2>Cancel Lesson</h2>
          <ModalFormGroup>
            <Label>Cancellation Reason:</Label>
            <ModalInput
              id="cancelledReason"
              type="text"
              value={cancelledReason}
              onChange={(e) => setCancelledReason(e.target.value)}
              placeholder="Enter reason for cancellation..."
            />
          </ModalFormGroup>
          <ModalActions>
            <ActionButton
              variant="secondary"
              type="button"
              onClick={closeAllModals}
            >
              Keep Lesson
            </ActionButton>
            <ActionButton
              variant="danger"
              type="button"
              onClick={handleConfirmCancel}
            >
              Cancel Lesson
            </ActionButton>
          </ModalActions>
        </ModalContent>
      </ModalOverlay>
    </ModalOverlayBlur>
  );
};

export default CancelLessonModal;

