import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { RootState, AppDispatch } from "../../store/store";
import { studentActions } from "../../store/studentSlice";
import {
  Container,
  Title,
  Spinner,
  ErrorContainer,
  ErrorLogo,
  Button,
} from "../Utils/Styled";
import StudentList from "./StudentList";
import DeleteModal from "./modals/DeleteModal";
import UpsertModal from "./modals/UpsertModal";
import { useModals } from "./hooks/useModals";
import { useStudentForm } from "./hooks/useStudentForm";
import { Student } from "../../models/Student";
import { LessonRecurring } from "../../models/LessonRecurring";
import { useLessonRecurringForm } from "./hooks/useLessonRecurringForm";
import { lessonRecurringActions, lessonInstanceActions } from "../../store/lessonSlice";

const StudentManagement: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { items: students, loading, error } = useSelector((state: RootState) => state.students);
  const { items: lessonRecurrings } = useSelector((state: RootState) => state.lessonRecurrings);

  const {
    modals,
    itemToDelete,
    itemTypeToDelete,
    upsertEntityType,
    editingId: modalEditingId,
    openUpsertModal,
    openDeleteModal,
    closeAllModals,
  } = useModals();

  const {
    studentForm,
    studentEditId,
    setStudentEditId,
    setStudentForm,
    resetStudentForm,
    handleStudentChange,
  } = useStudentForm();

  const {
    lessonRecurringForm,
    lessonRecurringEditId,
    setLessonRecurringEditId,
    setLessonRecurringForm,
    resetLessonRecurringForm,
    handleLessonRecurringChange,
    setLessonRecurringStudentId
  } = useLessonRecurringForm();

  const [originalLessonRecurring, setOriginalLessonRecurring] = React.useState<LessonRecurring | null>(null);

  useEffect(() => {
    dispatch(studentActions.fetchAll());
    dispatch(lessonRecurringActions.fetchAll());
  }, [dispatch]);

   // Handle escape key press to close all modals
    useEffect(() => {
      const handleKeyDown = (event: KeyboardEvent) => {
        if (event.key === 'Escape') {
          closeAllModals();
        }
      };
  
      // Add event listener when component mounts
      document.addEventListener('keydown', handleKeyDown);
  
      // Remove event listener when component unmounts
      return () => {
        document.removeEventListener('keydown', handleKeyDown);
      };
    }, [closeAllModals]);
  

  const handleAddStudentModal = () => {
    resetStudentForm();
    openUpsertModal("student");
  };

  const handleAddLessonRecurringModal = (student: Student) => {
    resetLessonRecurringForm();
    setLessonRecurringStudentId(student._id);
    openUpsertModal("lessonRecurring");
  };

  const handleEditLessonRecurringModal = (lesson: LessonRecurring) => {
    setOriginalLessonRecurring(lesson);
    const startDate = lesson.startDate ? new Date(lesson.startDate).toISOString().split('T')[0] : "";
    const endDate = lesson.endDate ? new Date(lesson.endDate).toISOString().split('T')[0] : "";

    setLessonRecurringForm({
      _id: lesson._id || "",
      studentId: lesson.studentId || "",
      fee: lesson.fee || 0,
      startDate: startDate,
      endDate: endDate,
      dayOfWeek: lesson.dayOfWeek || "",
      startTime: lesson.startTime || "",
      endTime: lesson.endTime || "",
      notes: lesson.notes || "",
    });
    setLessonRecurringEditId(lesson._id);
    openUpsertModal("lessonRecurring", lesson._id);
  };

  const handleEditStudentModal = (student: any) => {
    setStudentForm({
      _id: student._id || "",
      name: student.name || "",
      email: student.email || "",
      phone: student.phone || "",
      dateOfBirth: student.dateOfBirth || "",
      notes: student.notes || "",
      createdAt: student.createdAt || new Date(),
    });
    setStudentEditId(student._id);
    openUpsertModal("student", student._id);
  };

  const handleLessonRecurringSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const now = new Date();

    // Handle new lesson recurring creation
    if (lessonRecurringEditId === undefined || lessonRecurringEditId === "") {
      dispatch(lessonRecurringActions.add({
        ...lessonRecurringForm,
        createdAt: now,
        updatedAt: now,
      }));
      closeAllModals();
      resetLessonRecurringForm();
      return;
    }

    // For update, ensure createdAt is preserved from original
    const updatedLessonRecurring = {
      ...lessonRecurringForm,
      _id: lessonRecurringEditId,
      createdAt: originalLessonRecurring ? originalLessonRecurring.createdAt : now,
      updatedAt: now,
    };

    dispatch(lessonRecurringActions.update(updatedLessonRecurring));
    setLessonRecurringEditId(undefined);
    setOriginalLessonRecurring(null);
    closeAllModals();
    resetLessonRecurringForm();
  };

  const handleStudentSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const now = new Date();

    // Handle new student creation
    if (studentEditId === undefined || studentEditId === "") {
      dispatch(studentActions.add({
        ...studentForm,
        createdAt: now,
        updatedAt: now,
      }));
      closeAllModals();
      resetStudentForm();
      return;
    }

    dispatch(studentActions.update({
      ...studentForm,
      _id: studentEditId,
      updatedAt: now,
    }));
    setStudentEditId(undefined);
    closeAllModals();
    resetStudentForm();
  };

  const handleDelete = () => {
    if (!itemToDelete || !itemToDelete._id) {
      closeAllModals();
      return;
    }

    // Delete lesson recurring
    if (itemTypeToDelete === 'lessonRecurring') {
      dispatch(lessonRecurringActions.remove(itemToDelete._id));
    }

    // Delete student and associated lesson recurrings and instances
    else if (itemTypeToDelete === 'student') {
      dispatch(studentActions.remove(itemToDelete._id));
      // Also remove associated lesson recurrings
      const associatedLessons = lessonRecurrings.filter(lesson => lesson.studentId === itemToDelete._id);
      associatedLessons.forEach(lesson => {
        if (lesson._id) {
          dispatch(lessonRecurringActions.remove(lesson._id));
        }
      });

      // Also remove associated lesson instances
      dispatch(lessonInstanceActions.removeByStudentId(itemToDelete._id));
      if (studentEditId === itemToDelete._id) {
        setStudentEditId(undefined);
        resetStudentForm();
      }
    } 
    closeAllModals();
  };

  if (loading) {
    return <Spinner />;
  }

  if (error) {
    return (
      <ErrorContainer>
        <ErrorLogo>🚫</ErrorLogo>
        <h2 style={{ color: "#e53e3e", marginBottom: 12 }}>Oops! Something went wrong</h2>
        <p style={{ color: "#c53030", fontSize: "1.1rem" }}>{error}</p>
      </ErrorContainer>
    );
  }

  return (
    <Container>
      <Title>🎹 Student Management</Title>
      <div style={{ textAlign: "right", marginBottom: 24 }}>
        <Button onClick={handleAddStudentModal}>Add Student</Button>
      </div>

      <h2 style={{ color: "#2d3748", marginBottom: 18 }}>
        All Students
        <span style={{ fontSize: "0.9em", color: "#718096", marginLeft: "12px" }}>
          ({lessonRecurrings.length} recurring lessons)
        </span>
      </h2>
      <StudentList
        students={students}
        lessonRecurring={lessonRecurrings}
        loading={loading}
        onEdit={handleEditStudentModal}
        onDelete={(student) => openDeleteModal(student, 'student')}
      onAddLessonRecurring={(student) => handleAddLessonRecurringModal(student)}
      onEditLessonRecurring={(lesson) => handleEditLessonRecurringModal(lesson)}
      onDeleteLessonRecurring={(lesson) => openDeleteModal(lesson, 'lessonRecurring')}
      />

      <UpsertModal
        open={modals.upsert}
        form={upsertEntityType === "student" ? studentForm : lessonRecurringForm}
        loading={loading}
        modalMode={modalEditingId ? "edit" : "add"}
        editingId={modalEditingId}
        entityType={upsertEntityType}
        onChange={upsertEntityType === "student" ? handleStudentChange : handleLessonRecurringChange}
        onSubmit={upsertEntityType === "student" ? handleStudentSubmit : handleLessonRecurringSubmit}
        onCancel={() => {
          closeAllModals();
          resetStudentForm();
        }}
      />

      <DeleteModal
        open={modals.delete}
        onClose={closeAllModals}
        itemToDelete={itemToDelete}
        itemType={itemTypeToDelete === 'lessonRecurring' ? 'lesson' : 'student'}
        onDelete={handleDelete}
        loading={loading}
      />

    </Container>
  );
};

export default StudentManagement;
