import { createEntitySlice } from './createEntitySlice';
import { LessonInstance } from '../models/LessonInstance';
import { LessonInstanceService } from '../services/lessonServices';
import { LessonRecurring } from '../models/LessonRecurring';
import { LessonRecurringService } from '../services/lessonServices';

const lessonInstanceService = new LessonInstanceService();
const lessonInstanceSlice = createEntitySlice<LessonInstance>('lessonInstance', lessonInstanceService);
const lessonRecurringService = new LessonRecurringService();
const lessonRecurringSlice = createEntitySlice<LessonRecurring>('lessonRecurring', lessonRecurringService);

export const lessonInstanceReducer = lessonInstanceSlice.reducer;
export const lessonInstanceActions = lessonInstanceSlice.actions;
export const lessonRecurringReducer = lessonRecurringSlice.reducer;
export const lessonRecurringActions = lessonRecurringSlice.actions;
