import React, { useState, useEffect, useMemo } from "react";
import styled from "styled-components";
import { useSelector, useDispatch } from "react-redux";
import { RootState, AppDispatch } from "../store/store";
import { studentActions } from "../store/studentSlice";
import { lessonInstanceActions, lessonRecurringActions } from "../store/lessonSlice";
import ViewEventModal from "./Utils/modals/ViewEventModal";
import { useModals } from "./Utils/hooks/useModals";
import { LessonInstance } from "../models/LessonInstance";
import { LessonRecurring, daysOfWeekMap } from "../models/LessonRecurring";
import { Student } from "../models/Student";
import {
  Container,
  Title,
  Button,
  StatusBadge,
  Input,
  Label,
  FilterSection,
  FilterGroup,
  TableContainer,
  Table,
  TableHeaderCell,
  TableCell,
  LoadingSpinner,
  ViewButton,
  NoLessonsMessage,
  StatusFilterContainer,
  StatusCheckboxItem,
} from "./Utils/Styled";
import CompleteLessonModal from "./Utils/modals/CompleteLessonModal";
import EditEventModal from "./Utils/modals/EditEventModal";
import AddLessonModal from "./Utils/modals/AddLessonModal";
import CancelLessonModal from "./Utils/modals/CancelLessonModal";
import SignatureModal from "./Utils/modals/SignatureModal";
import { generateCalendarEvents } from "./HomePage/utils/generateCalendarEvents";

const LessonOverview: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();

  // Redux state
  const students = useSelector((state: RootState) => state.students.items || []);
  const lessonInstances = useSelector((state: RootState) => state.lessonsInstances.items || []);
  const lessonRecurrings = useSelector((state: RootState) => state.lessonRecurrings.items || []);
  const lessonsLoading = useSelector((state: RootState) => state.lessonsInstances.loading);

  // Modal management
  const {
      modalState,
      signatureSigner,
      setSignatureSigner,
      teacherSignature,
      studentSignature,
      feePaid,
      setFeePaid,
      setSignature,
      openAddLessonModal,
      closeAddLessonModal,
      openViewEventModal,
      openEditEventModal,
      openSignatureModal,
      closeSignatureModal,
      openCompleteLessonModal,
      closeCompleteLessonModal,
      openCancelLessonModal,
      closeAllModals,
  } = useModals();

   // Handle escape key press to close all modals
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        closeAllModals();
      }
    };

    // Add event listener when component mounts
    document.addEventListener('keydown', handleKeyDown);

    // Remove event listener when component unmounts
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [closeAllModals]);

  // Filter state
  const today = new Date();
  const oneWeekAgo = new Date(today);
  oneWeekAgo.setDate(today.getDate() - 7);
  const oneWeekFromNow = new Date(today);
  oneWeekFromNow.setDate(today.getDate() + 7);

  const formatDateForInput = (date: Date): string => {
    return date.toISOString().split("T")[0];
  };

  const [startDate, setStartDate] = useState<string>(formatDateForInput(oneWeekAgo));
  const [endDate, setEndDate] = useState<string>(formatDateForInput(oneWeekFromNow));
  const [selectedStudentId, setSelectedStudentId] = useState<string>("");
  const [selectedStatuses, setSelectedStatuses] = useState<string[]>([]);
  const [selectedLesson, setSelectedLesson] = useState<LessonInstance | null>(null);

  // Load students and lessonInstances on mount
  useEffect(() => {
    const startDateObj = new Date(startDate);
    const endDateObj = new Date(endDate);
    dispatch(studentActions.fetchAll() as any);
    dispatch(lessonInstanceActions.fetchByStartEndDate({startDate:startDateObj, endDate:endDateObj}) as any);
    dispatch(lessonRecurringActions.fetchAll() as any);
  }, [dispatch,startDate, endDate]);

  // Helper functions
  const getStudentName = (studentId: string): string => {
    const student = students.find((s: Student) => s._id === studentId);
    return student?.name || "Unknown Student";
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-CA", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const getDayOfWeek = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", { weekday: "long" });
  };

  const formatTime = (timeString: string): string => {
    // Handle time format (could be HH:mm or full datetime)
    const timePart = timeString.includes("T")
      ? timeString.split("T")[1].substring(0, 5)
      : timeString.substring(0, 5);
    return timePart || "00:00";
  };

  // Filter lessonInstances by date range, student, and status
  const lessonsToDisplay = useMemo(() => {
    let events = generateCalendarEvents(lessonInstances, lessonRecurrings, students, startDate, endDate, selectedStudentId ? [selectedStudentId] : []);
    let filteredLessons: LessonInstance[] = events.map((event) => event.resource!) ;

    // Filter by status
    if (selectedStatuses.length > 0) {
      filteredLessons = filteredLessons.filter((lesson) => selectedStatuses.includes(lesson.status));
    }
    return filteredLessons;

  }, [lessonRecurrings, lessonInstances, startDate, endDate, selectedStudentId, selectedStatuses]);

  // Calculate total unpaid fees (expected fees of unacknowledged lessonInstances)
  const totalUnpaidFees = useMemo(() => {
    let unpaidLessons = [...lessonInstances];

    // Filter by date range
    if (startDate) {
      unpaidLessons = unpaidLessons.filter((lesson) => lesson.date >= startDate);
    }
    if (endDate) {
      unpaidLessons = unpaidLessons.filter((lesson) => lesson.date <= endDate);
    }

    // Filter by student
    if (selectedStudentId) {
      unpaidLessons = unpaidLessons.filter((lesson) => lesson.studentId === selectedStudentId);
    }

    // Filter by status (unacknowledged only)
    unpaidLessons = unpaidLessons.filter((lesson) => lesson.status === "unacknowledged");

    // Covert expectedFee to number and handle undefined
    unpaidLessons = unpaidLessons.map((lesson) => ({
      ...lesson,
      expectedFee: lesson.expectedFee ? Number(lesson.expectedFee) : 0,
    }));

    // Sum up expected fees
    return unpaidLessons.reduce((total, lesson) => total + (lesson.expectedFee || 0), 0);
  }, [lessonInstances, startDate, endDate, selectedStudentId]);

  // Clear filters
  const clearFilters = () => {
    setStartDate(formatDateForInput(oneWeekAgo));
    setEndDate(formatDateForInput(oneWeekFromNow));
    setSelectedStudentId("");
    setSelectedStatuses([]);
  };

  // Handle view lesson
  const handleViewLesson = (lesson: LessonInstance) => {
    setSelectedLesson(lesson);
    openViewEventModal();
  };

  // Calculate event start and end dates for ViewEventModal
  const getLessonDateTimes = (lesson: LessonInstance) => {
    const dateStr = lesson.date;
    const startTime = lesson.startTime.includes("T")
      ? lesson.startTime.split("T")[1].substring(0, 5)
      : lesson.startTime.substring(0, 5);
    const endTime = lesson.endTime.includes("T")
      ? lesson.endTime.split("T")[1].substring(0, 5)
      : lesson.endTime.substring(0, 5);

    const startDateTime = new Date(`${dateStr}T${startTime}`);
    const endDateTime = new Date(`${dateStr}T${endTime}`);

    return { startDateTime, endDateTime };
  };

  return (
    <Container>
      <Title>Lesson Overview</Title>

      <FilterSection>
        <FilterGroup>
          <Label htmlFor="startDate">Start Date</Label>
          <Input
            type="date"
            id="startDate"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
          />
        </FilterGroup>

        <FilterGroup>
          <Label htmlFor="endDate">End Date</Label>
          <Input
            type="date"
            id="endDate"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
          />
        </FilterGroup>

        <FilterGroup>
          <Label htmlFor="studentSelect">Student</Label>
          <select
            id="studentSelect"
            value={selectedStudentId}
            onChange={(e) => setSelectedStudentId(e.target.value)}
            style={{
              padding: "10px 12px",
              border: "1.5px solid #cbd5e1",
              borderRadius: "7px",
              fontSize: "1rem",
              background: "#f8fafc",
              minWidth: "200px",
              cursor: "pointer",
            }}
          >
            <option value="">All Students</option>
            {students.map((student: Student) => (
              <option key={student._id} value={student._id}>
                {student.name}
              </option>
            ))}
          </select>
        </FilterGroup>

        <FilterGroup>
          <Label>Status</Label>
          <StatusFilterContainer>
            {[
              { value: "scheduled", label: "Scheduled" },
              { value: "completed", label: "Completed" },
              { value: "unacknowledged", label: "Unacknowledged" },
              { value: "cancelled", label: "Cancelled" },
            ].map((status) => (
              <StatusCheckboxItem key={status.value}>
                <input
                  type="checkbox"
                  checked={selectedStatuses.includes(status.value)}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setSelectedStatuses([...selectedStatuses, status.value]);
                    } else {
                      setSelectedStatuses(
                        selectedStatuses.filter((s) => s !== status.value)
                      );
                    }
                  }}
                />
                <StatusBadge status={status.value as any}>{status.label}</StatusBadge>
              </StatusCheckboxItem>
            ))}
          </StatusFilterContainer>
        </FilterGroup>

        <Button variant="secondary" onClick={clearFilters}>
          Clear Filters
        </Button>
      </FilterSection>

      <div style={{ marginBottom: "20px", fontSize: "1.2rem", fontWeight: "bold", color: "#e74c3c" }}>
        Total Unacknowledged Fees: ${totalUnpaidFees}
      </div>

      {lessonsLoading ? (
        <LoadingSpinner />
      ) : (
        <TableContainer>
          {lessonsToDisplay.length > 0 ? (
            <Table>
              <thead>
                <tr>
                  <TableHeaderCell>Student</TableHeaderCell>
                  <TableHeaderCell>Day</TableHeaderCell>
                  <TableHeaderCell>Date</TableHeaderCell>
                  <TableHeaderCell>Start Time</TableHeaderCell>
                  <TableHeaderCell>End Time</TableHeaderCell>
                  <TableHeaderCell>Fee</TableHeaderCell>
                  <TableHeaderCell>Status</TableHeaderCell>
                  <TableHeaderCell>Action</TableHeaderCell>
                </tr>
              </thead>
              <tbody>
                {lessonsToDisplay.map((lesson) => {
                  const { startDateTime, endDateTime } = getLessonDateTimes(lesson);
                  return (
                    <tr key={lesson._id + lesson.studentId + lesson.date + lesson.date + lesson.startTime + lesson.endTime}>
                      <TableCell>{getStudentName(lesson.studentId)}</TableCell>
                      <TableCell>{getDayOfWeek(lesson.date)}</TableCell>
                      <TableCell>{formatDate(lesson.date)}</TableCell>
                      <TableCell>{formatTime(lesson.startTime)}</TableCell>
                      <TableCell>{formatTime(lesson.endTime)}</TableCell>
                      <TableCell>${lesson.expectedFee || "0.00"}</TableCell>
                      <TableCell>
                        <StatusBadge status={lesson.status}>
                          {lesson.status}
                        </StatusBadge>
                      </TableCell>
                      <TableCell>
                        <ViewButton onClick={() => handleViewLesson(lesson)}>
                          View
                        </ViewButton>
                      </TableCell>
                    </tr>
                  );
                })}
              </tbody>
            </Table>
          ) : (
            <NoLessonsMessage>
              {lessonInstances.length === 0
                ? "No lessons found. Add lessons to see them here."
                : "No lessons match the selected filters."}
            </NoLessonsMessage>
          )}
        </TableContainer>
      )}

      {selectedLesson && (
        <div>
          <ViewEventModal
            isOpen={modalState.viewEventModal}
            studentName={getStudentName(selectedLesson.studentId)}
            lessonInstance={selectedLesson}
            eventStart={getLessonDateTimes(selectedLesson).startDateTime}
            eventEnd={getLessonDateTimes(selectedLesson).endDateTime}
            closeAllModals={closeAllModals}
            openEditEventModal={openEditEventModal}
            openCompleteLessonModal={(expectedFee: number) =>
              openCompleteLessonModal(expectedFee)
            }
            openCancelLessonModal={openCancelLessonModal}
          />
          <CompleteLessonModal
            isOpen={modalState.completeLessonModal}
            lessonInstance={selectedLesson}
            setSignatureSigner={setSignatureSigner}
            openSignatureModal={openSignatureModal}
            teacherSignature={teacherSignature}
            studentSignature={studentSignature}
            feePaid={feePaid}
            setFeePaid={setFeePaid}
            onSubmit={() => {
              if (!selectedLesson) return;
              let updatedLessonInstance: LessonInstance = { ...selectedLesson };
              if (teacherSignature) {
                updatedLessonInstance.teacherSignature = {
                  signedAt: new Date().toISOString(),
                  imageUrl: teacherSignature,
                };
              }
              if (studentSignature) {
                updatedLessonInstance.studentSignature = {
                  signedAt: new Date().toISOString(),
                  imageUrl: studentSignature,
                };
              }
              updatedLessonInstance.actualFee = parseFloat(feePaid);
              if (teacherSignature && studentSignature) {
                updatedLessonInstance.status = "completed";
              }
              const startDateObj = new Date(startDate);
              const endDateObj = new Date(endDate);
              dispatch(lessonInstanceActions.update(updatedLessonInstance));
              dispatch(lessonInstanceActions.fetchByStartEndDate({startDate:startDateObj, endDate:endDateObj}) as any);
              closeCompleteLessonModal();
              setSelectedLesson(updatedLessonInstance)
            }}
            onClose={closeCompleteLessonModal}
          />
    
          <EditEventModal
            isOpen={modalState.editEventModal}
            lessonInstance={selectedLesson}
            studentName={students.find(s => s._id === (selectedLesson)?.studentId)?.name || ""}
            eventStart={new Date(`${selectedLesson.date}T${selectedLesson.startTime}`)}
            eventEnd={new Date(`${selectedLesson.date}T${selectedLesson.endTime}`)}
            closeAllModals={closeAllModals}
          />

          <CancelLessonModal
            isOpen={modalState.cancelLessonModal}
            lessonInstance={selectedLesson}
            closeAllModals={closeAllModals}
            onCancel={() => {
              // The actual cancellation logic is handled inside the CancelLessonModal
            }}
          />
    
          {/* <AddLessonModal
            isOpen={modalState.addLessonModal}
            onClose={closeAddLessonModal}
            prefillDate={AddLessonModalPrefillDate}
          /> */}
    
          <SignatureModal
            isOpen={modalState.signatureModal}
            onClose={closeSignatureModal}
            onSignatureSubmit={(signature: string) => {
              closeSignatureModal();
              setSignature(signatureSigner as "teacher" | "student", signature);
            }}
          />
        </div>
      )}
    </Container>
  );
};

export default LessonOverview;

