import { LessonInstance } from '../../../models/LessonInstance';
import { LessonRecurring } from '../../../models/LessonRecurring';
import { generateCalendarEvents } from './generateCalendarEvents';

export function updateLessonStatus(
  lessonInstances: LessonInstance[],
  lessonRecurrings: LessonRecurring[],
  students: any[],
  fromDate: string,
  toDate: string = new Date().toISOString().split('T')[0]
): { updatedInstances: LessonInstance[], newInstances: LessonInstance[] } {
  // Generate all calendar events to get the complete picture
  const allEvents = generateCalendarEvents(lessonInstances, lessonRecurrings, students, fromDate, toDate);
  
  const updatedInstances: LessonInstance[] = [];
  const newInstances: LessonInstance[] = [];
  
  // Process all events to identify overdue lessons
  allEvents.forEach(event => {
    if (!event.resource) return;
    
    const lessonInstance = event.resource as LessonInstance;

    // Skip future lessons
    const lessonDate = new Date(lessonInstance.date);
    lessonDate.setHours(parseInt(lessonInstance.startTime.split(':')[0], 10));
    lessonDate.setMinutes(parseInt(lessonInstance.startTime.split(':')[1], 10));
    lessonDate.setSeconds(0);
    lessonDate.setMilliseconds(0);
    const today = new Date();
    if (lessonDate >= today) {
      return;
    }

    // Update past lessons that are still "scheduled" to "unacknowledged"
    if (lessonInstance._id) {
      if (lessonInstance.status === 'scheduled') {
        const updatedInstance = {
          ...lessonInstance,
          status: 'unacknowledged' as const,
          updatedAt: new Date()
        };
        updatedInstances.push(updatedInstance);
      }
      return;
    } 

    // Create past lesson instances as "unacknowledged" if they don't already exist
    const student = students.find(s => s._id === lessonInstance.studentId);
    const newInstance: LessonInstance = {
      _id: '', // Will be assigned by backend
      studentId: lessonInstance.studentId,
      lessonRecurringId: lessonInstance.lessonRecurringId || '',
      date: lessonInstance.date,
      startTime: lessonInstance.startTime,
      endTime: lessonInstance.endTime,
      type: 'regular',
      status: 'unacknowledged',
      expectedFee: student?.fee || 0,
      actualFee: 0,
      createdAt: new Date(),
      updatedAt: new Date()
    };
    newInstances.push(newInstance);
  });
  
  return { updatedInstances, newInstances };
}
