import { useState } from "react";

const initialFormState = {
  _id: "",
  name: "",
  email: "",
  phone: "",
  dateOfBirth: "",
  notes: "",
  createdAt: new Date(),
};

export const useStudentForm = () => {
  const [studentForm, setStudentForm] = useState(initialFormState);
  const [studentEditId, setStudentEditId] = useState<string | undefined>(undefined);

  const resetStudentForm = () => {
    setStudentForm(initialFormState);
    setStudentEditId(undefined);
  };

  const handleStudentChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setStudentForm({ ...studentForm, [e.target.name]: e.target.value });
  };

  return {
    studentForm,
    studentEditId,
    setStudentEditId,
    setStudentForm,
    resetStudentForm,
    handleStudentChange,
  };
};
