import React, { useRef } from 'react';
import SignatureCanvas from 'react-signature-canvas';
import {
  ModalOverlay,
  ModalContent,
  ModalClose,
  Button,
  Title
} from '../../Utils/Styled';

interface SignatureModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSignatureSubmit: (signature: string) => void;
}

const SignatureModal: React.FC<SignatureModalProps> = ({
  isOpen,
  onClose,
  onSignatureSubmit
}) => {
  const sigCanvasRef = useRef<SignatureCanvas>(null);

  const handleSubmit = () => {
    if (!sigCanvasRef.current) return;

    if (sigCanvasRef.current.isEmpty()) {
      alert("Please provide a signature before submitting.");
      return;
    }

    const signature = sigCanvasRef.current.toDataURL('image/png');
    onSignatureSubmit(signature);
    sigCanvasRef.current.clear();
    onClose();
  };

  const handleClear = () => {
    sigCanvasRef.current?.clear();
  };

  if (!isOpen) return null;

  return (
    <ModalOverlay onClick={onClose}>
      <ModalContent onClick={(e) => e.stopPropagation()}>
        <ModalClose onClick={onClose}>×</ModalClose>
        <Title>Signature Required</Title>

        <div style={{ marginBottom: '20px' }}>
          <p style={{ color: '#4a5568', marginBottom: '16px', textAlign: 'center' }}>
            Please sign below to confirm your attendance
          </p>

          <div style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            overflow: 'hidden',
            marginBottom: '16px',
            width: 400,
            height: 200,
          }}>
            <SignatureCanvas
              ref={sigCanvasRef}
              penColor="black"
              canvasProps={{
                width: 400,
                height: 200,
                style: {
                  backgroundColor: '#f8fafc',
                  display: 'block',
                  touchAction: 'none',
                }
              }}
            />
          </div>

          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: '16px'
          }}>
            <Button variant="secondary" onClick={handleClear} type="button">
              Clear
            </Button>
            <span style={{
              fontSize: '0.9rem',
              color: '#718096',
              fontStyle: 'italic'
            }}>
              Draw your signature above
            </span>
          </div>
        </div>

        <div style={{
          display: 'flex',
          justifyContent: 'flex-end',
          gap: '12px'
        }}>
          <Button variant="secondary" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSubmit}>
            Submit Signature
          </Button>
        </div>
      </ModalContent>
    </ModalOverlay>
  );
};

export default SignatureModal;
